		// kept to mirror the Akka interface but is unused
	}

	msgsrv Ping() {
		int choice;
		choice = ?(1, 2, 3, 4, 5);
		if (choice == 1) {
			c1.Pong();
		} else if (choice == 2) {
			c2.Pong();
		} else if (choice == 3) {
			c3.Pong();
		} else if (choice == 4) {
			c4.Pong();
		} else {
			c5.Pong();
		}
	}

	msgsrv initial() {
		// nothing
	}
}

main {
	Client c1(hub);
	Client c2(hub);
	Client c3(hub);
	Client c4(hub);
